package com.johnny.hotel.cms;
import com.johnny.hotel.cms.CmsModels.*;import org.apache.ibatis.annotations.*;import java.time.LocalDateTime;import java.util.*;
@Mapper public interface CmsMapper{
 @Insert("INSERT INTO site_page(slug,locale,created_by) VALUES(#{slug},#{locale},#{createdBy})")@Options(useGeneratedKeys=true,keyProperty="id")int insertPage(Page x);
 @Insert("INSERT INTO site_page_version(page_id,version_no,status,title,seo_title,seo_description,social_preview_media_id,created_by,updated_by) VALUES(#{pageId},#{versionNo},#{status},#{title},#{seoTitle},#{seoDescription},#{socialPreviewMediaId},#{createdBy},#{updatedBy})")@Options(useGeneratedKeys=true,keyProperty="id")int insertVersion(PageVersion x);
 @Select("SELECT * FROM site_page WHERE id=#{id}")Page page(Long id);@Select("SELECT * FROM site_page WHERE id=#{id} FOR UPDATE")Page lockPage(Long id);
 @Select("SELECT * FROM site_page_version WHERE page_id=#{page} AND status='DRAFT' ORDER BY version_no DESC LIMIT 1")PageVersion draft(Long page);
 @Select("SELECT * FROM site_page_version WHERE page_id=#{page} AND status='PUBLISHED' ORDER BY version_no DESC LIMIT 1")PageVersion published(Long page);
 @Select("SELECT COALESCE(MAX(version_no),0) FROM site_page_version WHERE page_id=#{page}")int maxVersion(Long page);
 @Update("UPDATE site_page_version SET title=#{title},seo_title=#{seoTitle},seo_description=#{seoDescription},social_preview_media_id=#{socialPreviewMediaId},updated_by=#{updatedBy},version_no=version_no+1 WHERE id=#{id} AND status='DRAFT' AND version_no=#{versionNo}")int updateDraft(PageVersion x);
 @Update("UPDATE site_page_version SET status='ARCHIVED',updated_by=#{actor} WHERE page_id=#{page} AND status='PUBLISHED'")int archivePublished(@Param("page")Long page,@Param("actor")Long actor);
 @Update("UPDATE site_page_version SET status='PUBLISHED',published_at=#{at},updated_by=#{actor} WHERE id=#{id} AND status='DRAFT'")int publish(@Param("id")Long id,@Param("actor")Long actor,@Param("at")LocalDateTime at);
 @Update("UPDATE site_page_version SET status='ARCHIVED',updated_by=#{actor} WHERE id=#{id} AND status='PUBLISHED'")int unpublish(@Param("id")Long id,@Param("actor")Long actor);
 @Insert("INSERT INTO site_section(page_version_id,section_key,section_type,sort_order,payload,visibility,status) SELECT #{to},section_key,section_type,sort_order,payload,visibility,status FROM site_section WHERE page_version_id=#{from}")int cloneSections(@Param("from")Long from,@Param("to")Long to);
 @Insert("INSERT INTO site_section(page_version_id,section_key,section_type,sort_order,payload,visibility,status) VALUES(#{pageVersionId},#{sectionKey},#{sectionType},#{sortOrder},CAST(#{payload} AS JSON),#{visibility},#{status})")@Options(useGeneratedKeys=true,keyProperty="id")int insertSection(Section x);
 @Update("UPDATE site_section SET section_key=#{sectionKey},section_type=#{sectionType},sort_order=#{sortOrder},payload=CAST(#{payload} AS JSON),visibility=#{visibility},status=#{status},version=version+1 WHERE id=#{id} AND page_version_id=#{pageVersionId} AND version=#{version}")int updateSection(Section x);
 @Delete("DELETE FROM site_section WHERE id=#{id} AND page_version_id=#{version}")int deleteSection(@Param("id")Long id,@Param("version")Long version);
 @Update("UPDATE site_section SET sort_order=#{order},version=version+1 WHERE id=#{id} AND page_version_id=#{version}")int reorder(@Param("id")Long id,@Param("version")Long version,@Param("order")int order);
 @Select("SELECT * FROM site_section WHERE page_version_id=#{id} ORDER BY sort_order,id")List<Section> sections(Long id);
 @Select("SELECT p.*,v.id version_id,v.version_no,v.title,v.seo_title,v.seo_description,v.social_preview_media_id,v.published_at FROM site_page p JOIN site_page_version v ON v.page_id=p.id AND v.status='PUBLISHED' WHERE p.slug=#{slug} AND p.locale=#{locale} ORDER BY v.version_no DESC LIMIT 1")Map<String,Object> publicPage(@Param("slug")String slug,@Param("locale")String locale);
 @Select("<script>SELECT p.* FROM site_page p <where><if test='locale!=null'>locale=#{locale}</if><if test='q!=null'>AND slug LIKE CONCAT('%',#{q},'%')</if></where> ORDER BY update_time DESC,id DESC LIMIT #{offset},#{size}</script>")List<Page> pages(@Param("locale")String locale,@Param("q")String q,@Param("offset")int offset,@Param("size")int size);
 @Select("<script>SELECT COUNT(*) FROM site_page <where><if test='locale!=null'>locale=#{locale}</if><if test='q!=null'>AND slug LIKE CONCAT('%',#{q},'%')</if></where></script>")long pageCount(@Param("locale")String locale,@Param("q")String q);
 @Insert("INSERT INTO site_navigation(label,locale,target_type,target_value,sort_order,visible,open_mode,status,created_by,updated_by) VALUES(#{label},#{locale},#{targetType},#{targetValue},#{sortOrder},#{visible},#{openMode},#{status},#{createdBy},#{updatedBy})")@Options(useGeneratedKeys=true,keyProperty="id")int insertNav(Navigation x);
 @Update("UPDATE site_navigation SET label=#{label},locale=#{locale},target_type=#{targetType},target_value=#{targetValue},sort_order=#{sortOrder},visible=#{visible},open_mode=#{openMode},status=#{status},updated_by=#{updatedBy} WHERE id=#{id}")int updateNav(Navigation x);
 @Select("SELECT * FROM site_navigation WHERE locale=#{locale} AND visible=1 AND status='ACTIVE' ORDER BY sort_order,id")List<Navigation> publicNav(String locale);
 @Select("SELECT * FROM site_navigation ORDER BY locale,sort_order,id LIMIT #{offset},#{size}")List<Navigation> navs(@Param("offset")int offset,@Param("size")int size);@Select("SELECT COUNT(*) FROM site_navigation")long navCount();
 @Select("SELECT * FROM site_navigation WHERE id=#{id}")Navigation nav(Long id);
 @Insert("INSERT INTO marketing_promotion(title,subtitle,description,locale,cover_media_id,gallery_media_ids,start_at,end_at,status,priority,cta_type,cta_target,pricing_policy_id,created_by,updated_by) VALUES(#{title},#{subtitle},#{description},#{locale},#{coverMediaId},CAST(#{galleryMediaIds} AS JSON),#{startAt},#{endAt},#{status},#{priority},#{ctaType},#{ctaTarget},#{pricingPolicyId},#{createdBy},#{updatedBy})")@Options(useGeneratedKeys=true,keyProperty="id")int insertPromotion(Promotion x);
 @Update("UPDATE marketing_promotion SET title=#{title},subtitle=#{subtitle},description=#{description},locale=#{locale},cover_media_id=#{coverMediaId},gallery_media_ids=CAST(#{galleryMediaIds} AS JSON),start_at=#{startAt},end_at=#{endAt},status=#{status},priority=#{priority},cta_type=#{ctaType},cta_target=#{ctaTarget},pricing_policy_id=#{pricingPolicyId},updated_by=#{updatedBy} WHERE id=#{id}")int updatePromotion(Promotion x);
 @Select("SELECT * FROM marketing_promotion WHERE locale=#{locale} AND status='PUBLISHED' AND (start_at IS NULL OR start_at <= #{now}) AND (end_at IS NULL OR end_at > #{now}) ORDER BY priority DESC,id DESC")List<Promotion> publicPromotions(@Param("locale")String locale,@Param("now")LocalDateTime now);
 @Select("SELECT * FROM marketing_promotion ORDER BY create_time DESC,id DESC LIMIT #{offset},#{size}")List<Promotion> promotions(@Param("offset")int offset,@Param("size")int size);@Select("SELECT COUNT(*) FROM marketing_promotion")long promotionCount();
 @Select("SELECT * FROM marketing_promotion WHERE id=#{id}")Promotion promotion(Long id);
 @Select("SELECT COUNT(*) FROM dynamic_pricing_policy WHERE id=#{id} AND status=1")int pricingExists(Long id);
 @Insert("INSERT INTO hotel_location_content(locale,hotel_name,address,latitude,longitude,phone,contact,display_metadata,status,created_by,updated_by) VALUES(#{locale},#{hotelName},#{address},#{latitude},#{longitude},#{phone},#{contact},CAST(#{displayMetadata} AS JSON),#{status},#{createdBy},#{updatedBy}) ON DUPLICATE KEY UPDATE hotel_name=VALUES(hotel_name),address=VALUES(address),latitude=VALUES(latitude),longitude=VALUES(longitude),phone=VALUES(phone),contact=VALUES(contact),display_metadata=VALUES(display_metadata),status=VALUES(status),updated_by=VALUES(updated_by)")int upsertLocation(Location x);
 @Select("SELECT * FROM hotel_location_content WHERE locale=#{locale} AND status='PUBLISHED'")Location publicLocation(String locale);@Select("SELECT * FROM hotel_location_content WHERE locale=#{locale}")Location location(String locale);
 @Insert("INSERT INTO hotel_visual_scene(name,locale,scene_type,media_asset_id,preview_media_id,visibility,interaction_mode,camera_config,status,created_by,updated_by) VALUES(#{name},#{locale},#{sceneType},#{mediaAssetId},#{previewMediaId},#{visibility},#{interactionMode},CAST(#{cameraConfig} AS JSON),#{status},#{createdBy},#{updatedBy})")@Options(useGeneratedKeys=true,keyProperty="id")int insertScene(Scene x);
 @Update("UPDATE hotel_visual_scene SET name=#{name},locale=#{locale},scene_type=#{sceneType},media_asset_id=#{mediaAssetId},preview_media_id=#{previewMediaId},visibility=#{visibility},interaction_mode=#{interactionMode},camera_config=CAST(#{cameraConfig} AS JSON),status=#{status},updated_by=#{updatedBy} WHERE id=#{id}")int updateScene(Scene x);
 @Select("SELECT * FROM hotel_visual_scene WHERE id=#{id}")Scene scene(Long id);@Select("SELECT * FROM hotel_visual_scene WHERE locale=#{locale} AND status='PUBLISHED' AND visibility='PUBLIC' AND interaction_mode='PUBLIC_ORBIT_ONLY' ORDER BY id")List<Scene> publicScenes(String locale);
 @Select("SELECT * FROM hotel_visual_scene ORDER BY create_time DESC,id DESC LIMIT #{offset},#{size}")List<Scene> scenes(@Param("offset")int offset,@Param("size")int size);@Select("SELECT COUNT(*) FROM hotel_visual_scene")long sceneCount();
 @Insert("INSERT INTO scene_node_binding(scene_id,node_key,floor_reference,room_id) VALUES(#{sceneId},#{nodeKey},#{floorReference},#{roomId})")@Options(useGeneratedKeys=true,keyProperty="id")int insertBinding(Binding x);@Select("SELECT * FROM scene_node_binding WHERE scene_id=#{scene} ORDER BY id")List<Binding> bindings(Long scene);
 @Insert("INSERT INTO media_asset(asset_type,storage_key,public_url,original_filename,content_type,size_bytes,checksum,status,created_by) VALUES(#{assetType},#{storageKey},#{publicUrl},#{originalFilename},#{contentType},#{sizeBytes},#{checksum},#{status},#{createdBy})")@Options(useGeneratedKeys=true,keyProperty="id")int insertMedia(Media x);
 @Select("SELECT * FROM media_asset WHERE id=#{id}")Media media(Long id);@Select("SELECT * FROM media_asset ORDER BY create_time DESC,id DESC LIMIT #{offset},#{size}")List<Media> mediaPage(@Param("offset")int offset,@Param("size")int size);@Select("SELECT COUNT(*) FROM media_asset")long mediaCount();
 @Select("SELECT * FROM media_asset WHERE storage_key=#{key}")Media mediaByKey(String key);
 @Select("SELECT (SELECT COUNT(*) FROM site_page_version WHERE social_preview_media_id=#{id} AND status='PUBLISHED')+(SELECT COUNT(*) FROM marketing_promotion WHERE cover_media_id=#{id} AND status='PUBLISHED')+(SELECT COUNT(*) FROM hotel_visual_scene WHERE (media_asset_id=#{id} OR preview_media_id=#{id}) AND status='PUBLISHED')")int publishedReferences(Long id);
 @Update("UPDATE media_asset SET status='ARCHIVED' WHERE id=#{id} AND status='ACTIVE'")int archiveMedia(Long id);
}
